import type { InventoryItem, Recipe, Unit } from '@mise/domain';

const ing = (ingredientId: string, name: string, quantity: string, unit: Unit, optional = false) => ({ ingredientId, name, quantity, unit, optional });
type RecipeInput = Omit<Recipe, 'version' | 'servings' | 'leftoverDays' | 'reheating'>;
const recipe = (input: RecipeInput): Recipe => ({ ...input, version: 1, servings: 2, leftoverDays: 1, reheating: 'Refrigerate the second serving within 2 hours. Reheat until fully steaming, stirring halfway through.' });
const chickenSafety = 'Chicken is safely cooked at 165°F. Without a thermometer, cut into the thickest part: the center should be opaque white, the juices should run clear, and there should be no glossy pink or translucent flesh.';
const salmonSafety = 'Salmon is safely cooked at 145°F. Without a thermometer, check the thickest part: it should flake easily, look opaque around the edges, and be only slightly translucent in the center.';
const chickenRecipe = (input:Omit<RecipeInput,'protein'|'safetyNote'>):Recipe => recipe({...input,protein:'Chicken breast',safetyNote:chickenSafety,tags:[...input.tags,'chicken-first']});

export const recipes: Recipe[] = [
  recipe({id:'vodka-chicken-linguine',title:'Garlic vodka chicken linguine',description:'One whole chicken breast per plate with linguine in your garlic vodka tomato sauce.',cuisine:'Italian-American',protein:'Chicken breast',prepMinutes:12,cookMinutes:24,difficulty:'Easy',estimatedCost:'8.50',caloriesPerServing:720,proteinGramsPerServing:55,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('linguine','Linguine','6','oz'),ing('garlic-vodka-sauce','Garlic vodka tomato sauce','1.5','cup'),ing('parmesan','Parmesan','0.5','cup'),ing('spinach','Baby spinach','4','oz'),ing('salt','Salt','0.5','tsp'),ing('pepper','Black pepper','0.25','tsp')],steps:['Fill a medium pot two-thirds full with water, cover, and bring to a rolling boil over high heat. Put each chicken breast flat on a board. If one end is much thicker, cover with plastic wrap and gently pound the thick end until the breast is about 3/4 inch thick. Season both sides with salt and pepper.','Add linguine to the boiling water. Stir immediately, then cook for the shortest time on the package. Before draining, scoop out 1/2 cup pasta water. Drain without rinsing.','Heat 1 tablespoon oil in a large skillet over medium-high for 1 minute. Add the chicken with space between the pieces. Cook without moving for 5 to 6 minutes, flip, lower to medium, and cook 5 to 7 minutes more. Cut a small slit into the thickest breast; the center should be opaque white with no glossy pink. Rest on a clean plate for 5 minutes.','Lower the skillet to medium-low. Add vodka sauce and spinach, cover, and simmer 3 minutes. Stir in linguine, parmesan, and 1/4 cup pasta water. Toss for 1 to 2 minutes; add more pasta water a spoonful at a time if the sauce looks tight.','Put one whole chicken breast on each plate. Leave it whole or slice crosswise into 1/2-inch strips after resting. Divide the sauced linguine beside it and finish with parmesan.'],tags:['pantry-first','pasta','chicken-first'],safetyNote:chickenSafety,equipment:['Medium pot','Large skillet','Tongs','Cutting board']}),

  recipe({id:'slap-ya-mama-chicken-rice',title:'Slap Ya Mama chicken rice bowls',description:'Cajun-spiced chicken breast, basmati rice, peppers, and a cool drizzle.',cuisine:'Cajun-inspired',protein:'Chicken breast',prepMinutes:12,cookMinutes:22,difficulty:'Easy',estimatedCost:'7.80',caloriesPerServing:640,proteinGramsPerServing:52,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('slap-ya-mama','Slap Ya Mama seasoning','1','tsp'),ing('bell-pepper','Bell pepper','1','count'),ing('onion','Yellow onion','0.5','count'),ing('yum-yum-sauce','Yum yum sauce','2','tbsp'),ing('smoked-paprika','Smoked paprika','0.5','tsp')],steps:['Rinse basmati rice in a fine strainer until the water is mostly clear. Put it in the rice cooker with 1 1/4 cups water and start the white-rice cycle. Rest it closed for 5 minutes after the cycle ends, then fluff.','Cut the bell pepper from top to bottom, remove the stem and seeds, and slice into 1/4-inch strips. Peel the onion and slice into thin half-moons. Pound the thick ends of the chicken to about 3/4 inch.','Mix Slap Ya Mama and paprika, then sprinkle lightly over both sides of the chicken; the blend already contains salt. Heat 1 tablespoon oil over medium-high. Cook the chicken 5 to 6 minutes without moving, flip, lower to medium, and cook another 5 to 7 minutes. Check the thickest center, then rest 5 minutes.','In the same skillet over medium-high, cook the pepper and onion for 5 to 7 minutes, stirring every minute, until the onion is soft and the pepper bends easily. Add 2 tablespoons water and scrape up the browned seasoning.','Slice each rested breast crosswise into 1/2-inch strips. Divide rice and vegetables between bowls, place one complete breast on each, and drizzle each serving with 1 tablespoon yum yum sauce.'],tags:['rice-bowl','cajun','chicken-first'],safetyNote:chickenSafety,equipment:['Rice cooker','Large skillet','Cutting board']}),

  recipe({id:'teriyaki-chicken-broccoli',title:'Teriyaki chicken and broccoli',description:'A glossy teriyaki chicken breast with steamed broccoli and basmati rice.',cuisine:'Japanese-inspired',protein:'Chicken breast',prepMinutes:10,cookMinutes:23,difficulty:'Easy',estimatedCost:'8.20',caloriesPerServing:610,proteinGramsPerServing:51,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('teriyaki-sauce','Teriyaki sauce','0.5','cup'),ing('broccoli','Broccoli','10','oz'),ing('soy','Soy sauce','1','tbsp'),ing('red-pepper-flakes','Red chili pepper flakes','0.25','tsp'),ing('garlic-salt','Garlic salt','0.5','tsp')],steps:['Rinse the rice and cook it in the rice cooker with 1 1/4 cups water. Cut broccoli into bite-size florets about 1 1/2 inches wide; peel the thick stem and slice it into 1/4-inch coins so it can be steamed too.','Pound the thick end of each chicken breast to about 3/4 inch and season lightly with garlic salt. Heat 1 tablespoon oil in a skillet over medium-high. When it shimmers, add chicken and cook without moving for 5 to 6 minutes.','Flip the chicken, lower to medium, and cook 5 to 7 minutes more. Cut into the thickest part to make sure it is opaque white with no pink or translucent center. Transfer to a clean plate and rest 5 minutes.','Steam broccoli in the rice cooker basket for the final 5 to 7 minutes, or put it in the skillet with 1/4 cup water, cover, and steam over medium for 4 to 5 minutes. It is ready when bright green and easily pierced with a fork.','Simmer teriyaki sauce, soy sauce, and chili flakes in the empty skillet over medium-low for 2 minutes. Slice the chicken crosswise, return it to the glaze for 30 seconds, and serve one breast per bowl with rice and broccoli.'],tags:['rice-bowl','teriyaki','chicken-first'],safetyNote:chickenSafety,equipment:['Rice cooker with steamer basket','Large skillet','Cutting board']}),

  recipe({id:'yum-yum-chicken-fried-rice',title:'Yum yum chicken fried rice plates',description:'Whole seared chicken breasts over quick egg fried Minute Rice with vegetables.',cuisine:'Asian-inspired',protein:'Chicken breast',prepMinutes:12,cookMinutes:20,difficulty:'Easy',estimatedCost:'7.50',caloriesPerServing:680,proteinGramsPerServing:57,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('minute-rice','Minute Rice','1','cup'),ing('eggs','Eggs','2','count'),ing('soy','Soy sauce','2','tbsp'),ing('yum-yum-sauce','Yum yum sauce','2','tbsp'),ing('frozen-vegetables','Frozen peas and carrots','1','cup'),ing('garlic-salt','Garlic salt','0.5','tsp')],steps:['Cook Minute Rice according to its package. Spread the cooked rice on a large plate for 5 minutes so steam escapes; drier rice fries instead of turning mushy.','Pound chicken to an even 3/4 inch and season with garlic salt. Heat 1 tablespoon oil over medium-high. Cook 5 to 6 minutes on the first side and 5 to 7 minutes on the second over medium. Check the thickest center, then rest on a clean plate.','Beat the eggs in a bowl. Add frozen vegetables to the skillet over medium-high and stir 3 minutes. Push them aside, add a splash of oil, pour in eggs, and stir for 60 to 90 seconds until softly scrambled.','Add rice and soy sauce. Break up clumps and toss for 3 to 4 minutes until the rice is very hot and a few grains begin to brown. Taste before adding salt because soy sauce is salty.','Divide fried rice between plates. Serve one whole chicken breast on each, slicing it crosswise if preferred, and spoon 1 tablespoon yum yum sauce over each breast.'],tags:['quick','rice','chicken-first'],safetyNote:chickenSafety,equipment:['Large skillet','Small bowl','Spatula']}),

  recipe({id:'air-fryer-chicken-parmesan',title:'Air-fryer garlic chicken parmesan',description:'Crisp breadcrumb chicken with red tomato sauce, parmesan, and linguine.',cuisine:'Italian-American',protein:'Chicken breast',prepMinutes:18,cookMinutes:22,difficulty:'Medium',estimatedCost:'9.00',caloriesPerServing:760,proteinGramsPerServing:61,cleanup:3,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('breadcrumbs','Garlic & herb Progresso bread crumbs','1','cup'),ing('eggs','Eggs','1','count'),ing('red-tomato-sauce','Red tomato sauce','1.5','cup'),ing('parmesan','Parmesan','0.5','cup'),ing('linguine','Linguine','6','oz'),ing('red-pepper-flakes','Red chili pepper flakes','0.125','tsp')],steps:['Preheat the air fryer to 390°F for 3 minutes. If a chicken breast is thicker than 1 inch, slice it horizontally into one thinner piece or pound the thick end until the breast is an even 1/2 to 3/4 inch.','Beat the egg in a shallow bowl. Mix breadcrumbs and half the parmesan in a second bowl. Dip each breast in egg, let extra drip off, then press both sides into crumbs. Spray or brush both sides lightly with oil.','Air-fry in one layer for 6 minutes, flip with tongs, and cook another 5 to 7 minutes. Cut into the thickest piece; the meat should be opaque white and the coating crisp. Cook 2 minutes more if needed.','Meanwhile, boil linguine according to the package. Warm tomato sauce in a small saucepan over medium-low for 5 minutes. Drain pasta and mix it with half the sauce.','Spoon a thin layer of sauce over each cooked breast, add remaining parmesan, and air-fry 1 to 2 minutes to warm the topping. Serve one breast per person with linguine and remaining sauce.'],tags:['air-fryer','crispy','chicken-first'],safetyNote:chickenSafety,equipment:['Air fryer','Medium pot','Small saucepan','Two shallow bowls']}),

  recipe({id:'tomato-curry-chicken',title:'Tomato curry chicken with basmati rice',description:'Chicken breast simmered in a warm tomato curry with tender peppers.',cuisine:'Indian-inspired',protein:'Chicken breast',prepMinutes:13,cookMinutes:27,difficulty:'Easy',estimatedCost:'8.40',caloriesPerServing:630,proteinGramsPerServing:52,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('red-tomato-sauce','Red tomato sauce','1.5','cup'),ing('curry-powder','Curry powder','2','tsp'),ing('cayenne','Cayenne pepper','0.125','tsp'),ing('onion','Yellow onion','0.5','count'),ing('bell-pepper','Bell pepper','1','count'),ing('chicken-bouillon','Chicken bouillon','1','tsp')],steps:['Rinse rice and start it in the rice cooker with 1 1/4 cups water. Peel and dice onion into 1/4-inch pieces. Remove pepper stem and seeds and cut the flesh into 1/2-inch squares.','Cut each chicken breast lengthwise into strips about 1 inch wide, then cut those into 1-inch chunks. Keeping the pieces the same size helps them finish together. Sprinkle with 1 teaspoon curry powder.','Heat 1 tablespoon oil in a deep skillet over medium-high. Add chicken in one layer and leave it alone for 3 minutes. Turn pieces and cook 3 minutes more; they do not need to be fully cooked yet. Move them to a clean bowl.','Lower to medium. Cook onion and pepper for 5 minutes. Add remaining curry powder and cayenne for 30 seconds. Add tomato sauce, bouillon, and 1/2 cup water; bring to a gentle bubble.','Return chicken and juices to the sauce. Cover and simmer on medium-low for 6 to 8 minutes, stirring once. Cut the largest chunk in half; it should be opaque white throughout. Divide the curry so each serving gets the pieces from one breast.'],tags:['curry','one-pan','chicken-first'],safetyNote:chickenSafety,equipment:['Rice cooker','Deep skillet','Cutting board']}),

  recipe({id:'lemon-pepper-chicken-fettuccine',title:'Lemon pepper chicken fettuccine',description:'Peppery seared chicken with parmesan fettuccine and wilted spinach.',cuisine:'Italian-inspired',protein:'Chicken breast',prepMinutes:10,cookMinutes:24,difficulty:'Easy',estimatedCost:'8.80',caloriesPerServing:700,proteinGramsPerServing:55,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('fettuccine','Fettuccine','6','oz'),ing('lemon-pepper','Lemon & pepper seasoning','1.5','tsp'),ing('parmesan','Parmesan','0.5','cup'),ing('spinach','Baby spinach','4','oz'),ing('chicken-broth','Chicken broth','0.75','cup'),ing('garlic-salt','Garlic salt','0.25','tsp')],steps:['Bring a medium pot of water to a rolling boil. Pound the thick ends of chicken to about 3/4 inch. Season both sides with lemon-pepper and only a small pinch of garlic salt because both blends may contain salt.','Cook fettuccine for the shortest package time, stirring during the first minute. Reserve 1/2 cup pasta water and drain without rinsing.','Heat 1 tablespoon oil over medium-high. Add chicken and cook untouched for 5 to 6 minutes. Flip, lower to medium, and cook 5 to 7 minutes. Check the thickest center for opaque white meat and clear juices. Rest 5 minutes.','Add broth to the skillet over medium and scrape up the browned bits. Add spinach and cook 2 minutes. Lower the heat, add fettuccine and parmesan, and toss vigorously. Add pasta water 1 tablespoon at a time until smooth.','Slice each breast crosswise into 1/2-inch strips and put one breast on each portion of pasta. Finish with a small extra pinch of lemon-pepper seasoning.'],tags:['pasta','lemon-pepper','chicken-first'],safetyNote:chickenSafety,equipment:['Medium pot','Large skillet','Tongs']}),

  recipe({id:'tapatio-chicken-tomato-rice',title:'Tapatío chicken tomato rice skillet',description:'Spicy chicken breast with tomato rice, corn, and peppers in one skillet.',cuisine:'Mexican-inspired',protein:'Chicken breast',prepMinutes:14,cookMinutes:28,difficulty:'Easy',estimatedCost:'8.10',caloriesPerServing:650,proteinGramsPerServing:52,cleanup:1,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('red-tomato-sauce','Red tomato sauce','1','cup'),ing('tapatio','Tapatío hot sauce','2','tbsp'),ing('corn','Frozen corn','1','cup'),ing('bell-pepper','Bell pepper','1','count'),ing('chicken-bouillon','Chicken bouillon','1','tsp'),ing('onion-powder','Onion powder','0.5','tsp')],steps:['Cut pepper into 1/2-inch squares. Pound chicken to an even 3/4 inch and season with onion powder. Stir tomato sauce, Tapatío, bouillon, and 1 cup water together.','Heat 1 tablespoon oil in a deep skillet over medium-high. Cook chicken 5 minutes on the first side and 4 minutes on the second; it will finish later. Move to a clean plate.','Add pepper to the skillet and cook 3 minutes. Stir in dry rice for 30 seconds, then pour in the tomato mixture. Bring to a gentle boil over medium-high, stirring once so no rice sticks.','Nestle chicken into rice. Cover, turn heat to low, and cook 15 minutes without lifting the lid. Add corn, cover, and cook 3 to 5 minutes until rice is tender and the thickest part of chicken is opaque white.','Turn off heat and let the covered skillet stand 5 minutes. Put one breast on each plate, fluff tomato rice around it, and add extra Tapatío at the table.'],tags:['one-pan','spicy','chicken-first'],safetyNote:chickenSafety,equipment:['Deep skillet with lid','Measuring cup','Cutting board']}),

  recipe({id:'teriyaki-salmon-basmati',title:'Teriyaki salmon and basmati bowls',description:'One salmon fillet per serving with teriyaki glaze, rice, and steamed broccoli.',cuisine:'Japanese-inspired',protein:'Salmon',prepMinutes:8,cookMinutes:18,difficulty:'Easy',estimatedCost:'14.00',caloriesPerServing:650,proteinGramsPerServing:42,cleanup:2,leftoverQuality:3,ingredients:[ing('salmon','Boneless salmon fillet','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('teriyaki-sauce','Teriyaki sauce','0.5','cup'),ing('broccoli','Broccoli','10','oz'),ing('soy','Soy sauce','1','tbsp'),ing('red-pepper-flakes','Red chili pepper flakes','0.125','tsp')],steps:['Rinse rice and start it in the rice cooker with 1 1/4 cups water. Cut broccoli into bite-size florets. Run a fingertip over each salmon fillet and pull out any hard pin bones with clean tweezers.','Pat salmon dry. Put it skin-side down, if it has skin, in a lightly oiled air-fryer basket. Brush the top with half the teriyaki sauce. Air-fry at 390°F for 7 minutes.','Steam broccoli in the rice cooker basket for the final 5 to 7 minutes. If there is no basket, steam in a covered skillet with 1/4 cup water over medium for 4 to 5 minutes.','Brush salmon with another spoonful of sauce and air-fry 2 to 4 minutes more. Press the thickest part with a fork: it should separate into moist flakes and look opaque around the edges, not raw and glassy.','Simmer remaining teriyaki sauce with soy sauce and chili flakes for 1 minute. Put one whole salmon fillet in each bowl with rice and broccoli and spoon over glaze.'],tags:['air-fryer','salmon','rice-bowl'],safetyNote:salmonSafety,equipment:['Air fryer','Rice cooker with steamer basket','Small saucepan']}),

  recipe({id:'lemon-pepper-salmon-linguine',title:'Lemon pepper salmon linguine',description:'One flaky salmon fillet per person over parmesan spinach linguine.',cuisine:'Italian-inspired',protein:'Salmon',prepMinutes:10,cookMinutes:20,difficulty:'Easy',estimatedCost:'14.50',caloriesPerServing:730,proteinGramsPerServing:45,cleanup:2,leftoverQuality:3,ingredients:[ing('salmon','Boneless salmon fillet','2','count'),ing('linguine','Linguine','6','oz'),ing('lemon-pepper','Lemon & pepper seasoning','1.5','tsp'),ing('parmesan','Parmesan','0.5','cup'),ing('spinach','Baby spinach','4','oz'),ing('chicken-broth','Chicken broth','0.5','cup'),ing('red-pepper-flakes','Red chili pepper flakes','0.125','tsp')],steps:['Bring a pot of water to a rolling boil. Check salmon for pin bones, pat dry, and season the flesh side with lemon-pepper.','Cook linguine for the shortest package time. Reserve 1/2 cup pasta water, then drain without rinsing.','Heat 1 tablespoon oil in a nonstick skillet over medium-high. Put salmon in skin-side down and cook 4 to 5 minutes. Flip carefully, lower to medium, and cook 3 to 5 minutes. The thickest part should separate into moist flakes and no longer look raw and glassy. Move to a plate.','Add broth and spinach to the skillet and simmer 2 minutes. Lower heat, add linguine, parmesan, and chili flakes, and toss. Add reserved pasta water 1 tablespoon at a time until glossy.','Divide linguine between plates and place one whole salmon fillet on each. If the skin stayed behind in the pan, discard it; keep the fillet whole unless you prefer it flaked.'],tags:['pasta','salmon','lemon-pepper'],safetyNote:salmonSafety,equipment:['Medium pot','Nonstick skillet','Tongs']}),

  recipe({id:'garlic-thyme-filet',title:'Garlic thyme filet mignon plates',description:'One filet per person with parmesan rice and skillet green beans.',cuisine:'American steakhouse',protein:'Filet mignon',prepMinutes:12,cookMinutes:25,difficulty:'Medium',estimatedCost:'24.00',caloriesPerServing:690,proteinGramsPerServing:47,cleanup:3,leftoverQuality:2,ingredients:[ing('filet-mignon','Filet mignon','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('green-beans','Green beans','8','oz'),ing('parmesan','Parmesan','0.5','cup'),ing('garlic-salt','Garlic salt','0.5','tsp'),ing('thyme','Thyme leaves','1','tsp'),ing('pepper','Black pepper','0.5','tsp')],steps:['Take filets out of the refrigerator 20 minutes before cooking. Pat very dry and season all sides with garlic salt, thyme, and pepper. Rinse and start rice in the rice cooker with 1 1/4 cups water.','Heat a cast-iron skillet empty over medium-high for 3 minutes. Add 1 tablespoon high-heat oil, then place filets in the pan. Sear without moving for 3 to 4 minutes until a dark brown crust forms.','Flip filets. Cook 3 to 4 minutes for medium-rare or 5 to 6 minutes for medium, briefly turning onto their sides to brown the edges. Without a thermometer, make a very small cut in one center: medium-rare is warm red-pink; medium is hot pink with only a little red. Rest 7 minutes.','While the meat rests, add trimmed green beans and 2 tablespoons water to the hot skillet. Cover and cook over medium for 4 minutes, then uncover and stir 2 minutes until bright green and tender.','Fold parmesan into hot rice. Serve one whole filet per person with half the rice and beans. Pour any juices from the resting plate over the steaks.'],tags:['steak','date-night','counted-protein'],equipment:['Cast-iron skillet','Rice cooker','Tongs']}),

  recipe({id:'spicy-tomato-eggs-rice',title:'Spicy tomato eggs over rice',description:'Soft scrambled eggs in a smoky Tapatío tomato sauce with basmati rice.',cuisine:'Pantry-inspired',protein:'Eggs',prepMinutes:8,cookMinutes:18,difficulty:'Easy',estimatedCost:'4.80',caloriesPerServing:540,proteinGramsPerServing:25,cleanup:2,leftoverQuality:3,ingredients:[ing('eggs','Eggs','6','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('red-tomato-sauce','Red tomato sauce','1','cup'),ing('tapatio','Tapatío hot sauce','1','tbsp'),ing('smoked-paprika','Smoked paprika','0.5','tsp'),ing('parmesan','Parmesan','0.25','cup'),ing('spinach','Baby spinach','4','oz')],steps:['Rinse and start rice in the rice cooker with 1 1/4 cups water. Crack eggs into a bowl, add 2 tablespoons water, and beat with a fork until no separate whites remain.','Heat a nonstick skillet over medium-low and add 1 teaspoon oil or butter. Pour in eggs. Slowly push a spatula through them every 10 seconds for 2 to 3 minutes, stopping while they are still soft and slightly glossy. Move to a clean bowl.','Add tomato sauce, Tapatío, and paprika to the skillet. Simmer over medium-low for 4 minutes, stirring twice.','Add spinach and stir for 1 to 2 minutes until fully wilted. Fold soft eggs into the sauce and heat 1 minute, just until no runny egg remains. Do not boil or the eggs will turn rubbery.','Divide rice between bowls and spoon tomato eggs over it. Finish each serving with half the parmesan and extra Tapatío if wanted.'],tags:['meatless','budget','eggs'],safetyNote:'Cook eggs until no liquid egg remains. The curds can stay soft, but they should not be runny.',equipment:['Rice cooker','Nonstick skillet','Mixing bowl']})
].map(item=>{if(item.ingredients.some(ingredient=>ingredient.ingredientId==='canola-oil'||ingredient.ingredientId==='olive-oil'))return item;const useOlive=/(Italian|Mediterranean)/i.test(item.cuisine);return {...item,ingredients:[...item.ingredients,ing(useOlive?'olive-oil':'canola-oil',useOlive?'Extra virgin olive oil':'Canola oil','1','tbsp')]}});

recipes.push(
  chickenRecipe({id:'honey-garlic-chicken-rice',title:'Honey garlic chicken rice plates',description:'Whole seared chicken breasts glazed with honey, soy, and garlic beside basmati rice and broccoli.',cuisine:'Asian-inspired',prepMinutes:10,cookMinutes:24,difficulty:'Easy',estimatedCost:'8.60',caloriesPerServing:650,proteinGramsPerServing:53,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('broccoli','Broccoli','10','oz'),ing('honey','Honey','2','tbsp'),ing('soy','Soy sauce','2','tbsp'),ing('garlic','Garlic cloves','2','count'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Rinse the rice until the water is mostly clear, then cook it in the rice cooker with 1 1/4 cups water. Cut broccoli into 1 1/2-inch florets and finely mince the garlic.','Pound the thick end of each breast until the whole piece is about 3/4 inch thick. Heat canola oil in a large skillet over medium-high for 1 minute, add chicken, and cook without moving for 5 to 6 minutes.','Flip the chicken and lower the heat to medium. Cook 5 to 7 minutes more, then cut into the thickest center to confirm opaque white meat and no glossy pink; move to a clean plate and rest 5 minutes.','Steam broccoli in the rice-cooker basket for the final 5 minutes, or cover it in a skillet with 1/4 cup water over medium for 4 to 5 minutes. Stir honey, soy, garlic, and 2 tablespoons water into the chicken skillet and simmer 2 minutes until glossy.','Turn each rested breast through the glaze for 30 seconds. Serve one whole breast per plate with rice and broccoli, spooning the remaining glaze over the chicken.'],tags:['glazed','rice','quick'],equipment:['Rice cooker','Large skillet','Cutting board']}),

  chickenRecipe({id:'orange-soy-chicken',title:'Orange soy chicken with peppers',description:'Bright orange-soy chicken breast strips with peppers, broccoli, and rice.',cuisine:'Chinese-inspired',prepMinutes:15,cookMinutes:22,difficulty:'Easy',estimatedCost:'9.10',caloriesPerServing:640,proteinGramsPerServing:51,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('orange','Orange','1','count'),ing('soy','Soy sauce','3','tbsp'),ing('bell-pepper','Bell pepper','1','count'),ing('broccoli','Broccoli','6','oz'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Start the rinsed rice in the rice cooker with 1 1/4 cups water. Cut the pepper into 1/4-inch strips and broccoli into small florets; zest the orange before squeezing out its juice.','Cut each chicken breast lengthwise into 1-inch strips, then cut those into pieces about 2 inches long. Whisk orange juice and zest with soy sauce and 1/4 cup water.','Heat canola oil in a wide skillet over medium-high. Spread chicken in one layer and sear 3 minutes without moving, turn the pieces, and cook another 3 to 4 minutes until the largest piece is opaque white inside; transfer to a clean bowl.','Add pepper and broccoli to the skillet with 2 tablespoons water. Cover for 2 minutes, then uncover and stir-fry 3 minutes until bright and crisp-tender.','Return chicken, pour in the orange-soy mixture, and bubble for 2 minutes until everything is coated. Divide evenly over rice so each bowl contains the meat from one breast.'],tags:['citrus','stir-fry','rice-bowl'],equipment:['Rice cooker','Wide skillet','Sharp knife']}),

  chickenRecipe({id:'slap-ya-mama-chicken-alfredo',title:'Slap Ya Mama chicken Alfredo',description:'Cajun-seasoned chicken breasts over creamy parmesan fettuccine and broccoli.',cuisine:'Italian-American',prepMinutes:15,cookMinutes:25,difficulty:'Medium',estimatedCost:'11.40',caloriesPerServing:820,proteinGramsPerServing:60,cleanup:3,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('fettuccine','Fettuccine','6','oz'),ing('slap-ya-mama','Slap Ya Mama seasoning','1','tsp'),ing('broccoli','Broccoli','8','oz'),ing('cream','Heavy cream','0.5','cup'),ing('parmesan','Parmesan','0.75','cup'),ing('olive-oil','Extra virgin olive oil','1','tbsp')],steps:['Bring a pot of water to a rolling boil. Cut broccoli into bite-size florets and pound each chicken breast to an even 3/4 inch; season lightly with Slap Ya Mama because it already contains salt.','Add fettuccine to the boiling water and stir during the first minute. Add broccoli for the final 3 minutes, reserve 3/4 cup pasta water, then drain without rinsing.','Heat olive oil in a skillet over medium-high. Sear chicken 5 to 6 minutes on the first side, flip, lower to medium, and cook 5 to 7 minutes more; check the thickest center for opaque white meat, then rest 5 minutes.','Lower the skillet to medium-low. Add cream and simmer gently for 2 minutes, then turn off the heat and whisk in parmesan plus enough pasta water to make a smooth sauce.','Toss fettuccine and broccoli in the sauce. Slice each rested breast crosswise into 1/2-inch strips and arrange one complete breast over each serving.'],tags:['cajun','alfredo','pasta'],equipment:['Medium pot','Large skillet','Tongs']}),

  chickenRecipe({id:'balsamic-thyme-chicken',title:'Balsamic thyme chicken and potatoes',description:'Herby seared chicken breasts with crisp potatoes, green beans, and a tangy pan glaze.',cuisine:'Italian-inspired',prepMinutes:15,cookMinutes:30,difficulty:'Easy',estimatedCost:'9.30',caloriesPerServing:590,proteinGramsPerServing:50,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('potato','Baby potatoes','0.75','lb'),ing('green-beans','Green beans','8','oz'),ing('balsamic-vinegar','Balsamic vinegar','2','tbsp'),ing('chicken-broth','Chicken broth','0.5','cup'),ing('thyme','Thyme leaves','1','tsp'),ing('olive-oil','Extra virgin olive oil','1','tbsp')],steps:['Heat the oven to 425°F. Halve potatoes smaller than a golf ball and quarter larger ones; toss with half the olive oil and thyme, spread cut-side down on a sheet pan, and roast 20 minutes.','Trim the dry stem ends from green beans. Add them to the sheet pan, toss carefully, and roast 10 minutes more until the potatoes pierce easily with a fork.','Pound chicken to 3/4 inch. Heat remaining oil in a skillet over medium-high, cook chicken 5 to 6 minutes without moving, flip, lower to medium, and cook 5 to 7 minutes until the thickest center is opaque white; rest 5 minutes.','Pour broth and balsamic vinegar into the skillet over medium heat. Scrape up the browned bits and simmer 3 to 5 minutes until the liquid lightly coats a spoon.','Serve one breast per plate with potatoes and beans. Spoon the glaze over the chicken only after it has rested so its juices stay inside.'],tags:['sheet-pan','herby','plated'],equipment:['Sheet pan','Large skillet','Tongs']}),

  chickenRecipe({id:'greek-lemon-chicken-potatoes',title:'Greek-style lemon chicken plates',description:'Lemon-pepper chicken breasts with oregano potatoes, zucchini, and parmesan.',cuisine:'Mediterranean-inspired',prepMinutes:15,cookMinutes:28,difficulty:'Easy',estimatedCost:'9.00',caloriesPerServing:610,proteinGramsPerServing:52,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('potato','Baby potatoes','0.75','lb'),ing('zucchini','Zucchini','1','count'),ing('lemon','Lemon','1','count'),ing('lemon-pepper','Lemon & pepper seasoning','1.5','tsp'),ing('parmesan','Parmesan','0.25','cup'),ing('olive-oil','Extra virgin olive oil','1.5','tbsp')],steps:['Heat the oven to 425°F. Cut potatoes into 3/4-inch chunks and zucchini into 1/2-inch half-moons; toss potatoes with 1 tablespoon oil and half the lemon-pepper seasoning.','Roast potatoes on a sheet pan for 15 minutes. Add zucchini, toss, and roast another 10 to 12 minutes until potatoes are browned and zucchini is tender.','Pound chicken to an even 3/4 inch and season with remaining lemon-pepper. Heat the remaining oil in a skillet over medium-high and sear chicken 5 to 6 minutes on the first side.','Flip chicken, lower to medium, and cook 5 to 7 minutes. Check the thickest center for opaque white meat and clear juices, then rest on a clean plate for 5 minutes.','Squeeze lemon over the roasted vegetables and toss with parmesan. Place one whole breast on each plate with half the vegetables.'],tags:['lemony','sheet-pan','plated'],equipment:['Sheet pan','Large skillet','Cutting board']}),

  chickenRecipe({id:'chicken-marsala-rice',title:'Chicken and mushroom pan sauce with rice',description:'Golden chicken breasts and mushrooms in a savory broth sauce over basmati rice.',cuisine:'Italian-American',prepMinutes:12,cookMinutes:25,difficulty:'Easy',estimatedCost:'10.20',caloriesPerServing:620,proteinGramsPerServing:53,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('mushrooms','Mushrooms','8','oz'),ing('chicken-broth','Chicken broth','0.75','cup'),ing('thyme','Thyme leaves','0.5','tsp'),ing('parmesan','Parmesan','0.25','cup'),ing('olive-oil','Extra virgin olive oil','1','tbsp')],steps:['Rinse rice and start it in the rice cooker with 1 1/4 cups water. Wipe mushrooms clean with a damp towel, trim the dry stem tips, and slice the caps and stems 1/4 inch thick.','Pound chicken to 3/4 inch and season with thyme, salt, and pepper. Heat olive oil over medium-high and cook chicken 5 to 6 minutes per side, lowering to medium after flipping.','Cut into the thickest part to confirm opaque white meat with no glossy pink. Transfer chicken to a clean plate and rest 5 minutes.','Add mushrooms to the same skillet over medium-high and cook 5 to 6 minutes, stirring only twice so they brown. Add broth and simmer 3 minutes while scraping up browned bits.','Fold parmesan into the cooked rice. Put one breast on each serving of rice and spoon mushrooms and pan sauce over the top.'],tags:['mushrooms','pan-sauce','rice'],equipment:['Rice cooker','Large skillet','Tongs']}),

  chickenRecipe({id:'chipotle-chicken-corn-bowls',title:'Chipotle chicken corn bowls',description:'Smoky chicken breast chunks with tomato rice, corn, peppers, and Tapatío.',cuisine:'Mexican-inspired',prepMinutes:14,cookMinutes:24,difficulty:'Easy',estimatedCost:'8.70',caloriesPerServing:660,proteinGramsPerServing:52,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('corn','Frozen corn','1','cup'),ing('bell-pepper','Bell pepper','1','count'),ing('chipotle-seasoning','Chipotle chili pepper seasoning','1','tsp'),ing('tapatio','Tapatío hot sauce','1','tbsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Start rinsed rice in the rice cooker with 1 1/4 cups water. Remove the pepper stem and seeds and cut the flesh into 1/2-inch squares.','Cut each breast lengthwise into 1-inch strips, then across into 1-inch chunks. Toss with chipotle seasoning so the pieces are evenly coated.','Heat canola oil in a skillet over medium-high. Spread chicken in one layer, sear 3 minutes, turn, and cook 3 to 4 minutes more until the largest piece is opaque white inside; move to a clean bowl.','Add pepper and corn to the skillet and cook 5 minutes, stirring once per minute. Return chicken, add Tapatío and 2 tablespoons water, and toss over medium heat for 1 minute.','Divide rice between bowls and top evenly with chicken and vegetables, making sure each serving gets the pieces from one breast.'],tags:['smoky','rice-bowl','spicy'],equipment:['Rice cooker','Large skillet','Sharp knife']}),

  chickenRecipe({id:'chicken-fajita-rice-bowls',title:'Chicken fajita rice bowls',description:'Sizzling strips of chicken breast, peppers, and onions over seasoned rice.',cuisine:'Mexican-inspired',prepMinutes:15,cookMinutes:22,difficulty:'Easy',estimatedCost:'8.50',caloriesPerServing:630,proteinGramsPerServing:51,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('bell-pepper','Bell peppers','2','count'),ing('onion','Yellow onion','0.5','count'),ing('smoked-paprika','Smoked paprika','1','tsp'),ing('cayenne','Cayenne pepper','0.125','tsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Rinse and start rice in the rice cooker with 1 1/4 cups water. Slice peppers into 1/4-inch strips and onion into thin half-moons.','Cut each chicken breast lengthwise into strips 1/2 inch wide. Toss with paprika, cayenne, and a pinch of salt.','Heat canola oil in a wide skillet over medium-high. Add chicken in one layer and cook 3 minutes without moving, then stir and cook 3 to 4 minutes until every strip is opaque white; transfer to a clean plate.','Add peppers and onion to the hot skillet. Cook 6 to 7 minutes, stirring each minute, until onions are soft and pepper edges are browned but the strips still hold their shape.','Return chicken and its juices for 1 minute. Divide rice between bowls and portion the strips so each bowl receives one breast plus half the vegetables.'],tags:['fajita','rice-bowl','quick'],equipment:['Rice cooker','Wide skillet','Cutting board']}),

  chickenRecipe({id:'garlic-parmesan-chicken-potatoes',title:'Garlic parmesan chicken and potatoes',description:'Air-fried chicken breasts and crisp potatoes with parmesan green beans.',cuisine:'American',prepMinutes:15,cookMinutes:26,difficulty:'Easy',estimatedCost:'9.20',caloriesPerServing:640,proteinGramsPerServing:56,cleanup:1,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('potato','Baby potatoes','0.75','lb'),ing('green-beans','Green beans','8','oz'),ing('parmesan','Parmesan','0.5','cup'),ing('garlic-salt','Garlic salt','1','tsp'),ing('thyme','Thyme leaves','0.5','tsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Preheat the air fryer to 390°F. Cut potatoes into 3/4-inch pieces, toss with half the canola oil, garlic salt, and thyme, and air-fry 10 minutes, shaking once.','Pound chicken breasts to an even 3/4 inch. Rub with remaining oil and a light sprinkle of garlic salt, then add them beside the potatoes without overlapping.','Air-fry 6 minutes, flip the chicken, and add trimmed green beans. Cook 5 to 7 minutes more until the chicken coating is browned.','Cut a slit in the thickest breast; the center should be opaque white with no pink. Remove chicken to rest 5 minutes and cook the vegetables 2 minutes longer if the potatoes are not fork-tender.','Toss hot potatoes and beans with parmesan. Serve one whole breast per person with half the vegetables.'],tags:['air-fryer','low-cleanup','parmesan'],equipment:['Air fryer','Mixing bowl','Tongs']}),

  chickenRecipe({id:'tomato-basil-chicken-linguine',title:'Tomato basil chicken linguine',description:'Seared chicken breasts with linguine, red tomato sauce, spinach, and fresh basil.',cuisine:'Italian',prepMinutes:12,cookMinutes:24,difficulty:'Easy',estimatedCost:'9.40',caloriesPerServing:710,proteinGramsPerServing:55,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('linguine','Linguine','6','oz'),ing('red-tomato-sauce','Red tomato sauce','1.5','cup'),ing('spinach','Baby spinach','4','oz'),ing('basil','Fresh basil','0.25','cup'),ing('parmesan','Parmesan','0.5','cup'),ing('olive-oil','Extra virgin olive oil','1','tbsp')],steps:['Bring a pot of water to a rolling boil. Stack basil leaves, roll them into a loose tube, and slice crosswise into thin ribbons; pound chicken to 3/4 inch and season with salt and pepper.','Cook linguine for the shortest package time. Reserve 1/2 cup pasta water, drain, and do not rinse.','Heat olive oil over medium-high and sear chicken 5 to 6 minutes. Flip, lower to medium, and cook 5 to 7 minutes until the thickest center is opaque white; rest on a clean plate for 5 minutes.','Lower the skillet to medium-low, add tomato sauce and spinach, and simmer covered for 3 minutes. Toss in linguine, half the basil, parmesan, and enough pasta water to loosen the sauce.','Slice each breast crosswise only after resting. Put one complete breast over each pasta serving and scatter the remaining basil on top.'],tags:['tomato','pasta','pantry-first'],equipment:['Medium pot','Large skillet','Tongs']}),

  chickenRecipe({id:'chicken-broccoli-rice-bake',title:'Chicken broccoli rice bake',description:'A small two-serving casserole of chicken breast, broccoli, rice, broth, and parmesan.',cuisine:'American',prepMinutes:15,cookMinutes:35,difficulty:'Medium',estimatedCost:'9.60',caloriesPerServing:700,proteinGramsPerServing:58,cleanup:3,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('minute-rice','Minute Rice','1','cup'),ing('broccoli','Broccoli','8','oz'),ing('chicken-broth','Chicken broth','1.5','cup'),ing('parmesan','Parmesan','0.75','cup'),ing('breadcrumbs','Garlic & herb Progresso bread crumbs','0.5','cup'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Heat the oven to 400°F and lightly coat an 8-inch baking dish with 1 teaspoon canola oil. Cut broccoli into small 1-inch florets.','Cut each chicken breast into 1-inch cubes, keeping the pieces from each breast in separate piles so portioning stays easy. Heat remaining oil in a skillet over medium-high and sear chicken 3 minutes, turn, and cook 2 minutes more.','Stir dry Minute Rice, hot broth, broccoli, half the parmesan, and chicken together in the baking dish. Cover tightly with foil and bake 18 minutes.','Remove the foil carefully, stir once, and cut the largest chicken cube in half. If it is still pink, cover and bake 5 minutes more; otherwise top with breadcrumbs and remaining parmesan.','Bake uncovered 5 to 7 minutes until the top is golden and the liquid is absorbed. Rest 5 minutes, then divide evenly so each serving contains one breast.'],tags:['casserole','comfort','meal-prep'],equipment:['Large skillet','8-inch baking dish','Foil']}),

  chickenRecipe({id:'curry-chicken-vegetable-soup',title:'Curry chicken vegetable soup',description:'Chicken breast, vegetables, broth, and Minute Rice in a warm curry-spiced soup.',cuisine:'Indian-inspired',prepMinutes:15,cookMinutes:28,difficulty:'Easy',estimatedCost:'8.20',caloriesPerServing:560,proteinGramsPerServing:49,cleanup:1,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('chicken-broth','Chicken broth','4','cup'),ing('minute-rice','Minute Rice','0.75','cup'),ing('carrot','Carrots','2','count'),ing('spinach','Baby spinach','4','oz'),ing('curry-powder','Curry powder','2','tsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Peel carrots and slice into 1/4-inch coins. Cut each chicken breast lengthwise into 1-inch strips, then across into 1-inch chunks.','Heat canola oil in a soup pot over medium-high. Add chicken in one layer and cook 3 minutes, stir, and cook 2 minutes more; move it to a clean bowl before it is fully cooked.','Lower to medium, add carrots and curry powder, and stir 1 minute. Pour in broth, scrape the bottom, and bring to a boil over high heat.','Lower to a steady simmer, add chicken, and cook 7 minutes. Add Minute Rice and simmer according to its package, usually 5 minutes; cut the largest chicken piece to confirm an opaque white center.','Stir in spinach for 1 minute until wilted. Divide the soup evenly, making sure each bowl receives the pieces from one chicken breast.'],tags:['soup','one-pot','curry'],equipment:['Soup pot','Cutting board','Wooden spoon']}),

  chickenRecipe({id:'ginger-soy-chicken-stir-fry',title:'Ginger soy chicken stir-fry',description:'Tender chicken breast pieces with broccoli, carrots, and a fresh ginger-soy sauce.',cuisine:'Chinese-inspired',prepMinutes:18,cookMinutes:18,difficulty:'Easy',estimatedCost:'9.20',caloriesPerServing:620,proteinGramsPerServing:51,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('broccoli','Broccoli','8','oz'),ing('carrot','Carrot','1','count'),ing('ginger','Fresh ginger','1','tbsp'),ing('soy','Soy sauce','3','tbsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Start rinsed rice in the rice cooker with 1 1/4 cups water. Cut broccoli into small florets, peel carrot and slice it diagonally into thin 1/8-inch ovals, and grate the ginger.','Cut each breast into strips 1/2 inch wide and about 2 inches long. Stir soy sauce, ginger, and 1/4 cup water together.','Heat canola oil in a wide skillet over high heat for 1 minute. Spread chicken in one layer and cook 3 minutes untouched, then stir for 2 to 3 minutes until the thickest strip is opaque white; transfer to a clean plate.','Add broccoli and carrot with 2 tablespoons water. Cover over medium-high for 2 minutes, then uncover and stir-fry 3 minutes until vegetables are bright and fork-tender.','Return chicken and add sauce. Toss for 1 to 2 minutes until bubbling, then divide over rice with the strips from one breast in each bowl.'],tags:['stir-fry','ginger','rice'],equipment:['Rice cooker','Wide skillet','Sharp knife']}),

  chickenRecipe({id:'tapatio-chicken-quesadillas',title:'Tapatío chicken quesadilla plates',description:'One chicken breast per serving folded into crisp cheese quesadillas with warm peppers.',cuisine:'Mexican-inspired',prepMinutes:15,cookMinutes:22,difficulty:'Easy',estimatedCost:'8.80',caloriesPerServing:760,proteinGramsPerServing:58,cleanup:2,leftoverQuality:3,ingredients:[ing('chicken','Chicken breast','2','count'),ing('tortilla','Flour tortillas','4','count'),ing('cheddar','Shredded cheddar','1','cup'),ing('bell-pepper','Bell pepper','1','count'),ing('tapatio','Tapatío hot sauce','2','tbsp'),ing('onion-powder','Onion powder','0.5','tsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Cut pepper into 1/4-inch strips. Pound chicken breasts to 3/4 inch and season with onion powder and a small pinch of salt.','Heat canola oil over medium-high. Cook chicken 5 to 6 minutes on the first side, flip, lower to medium, and cook 5 to 7 minutes until the thickest center is opaque white; rest 5 minutes.','Cook pepper strips in the same skillet over medium-high for 4 minutes. Slice each rested breast crosswise into thin 1/4-inch strips and toss with Tapatío.','Wipe the skillet, lower to medium, and lay in one tortilla. Cover half with 1/4 cup cheese, half of one sliced breast, peppers, and another 1/4 cup cheese; fold and cook 2 to 3 minutes per side until crisp. Repeat for the second serving.','Cut each quesadilla into three wedges and serve immediately. Each plate should contain the quesadilla made from one full chicken breast.'],tags:['quesadilla','spicy','crispy'],equipment:['Large skillet','Tongs','Sharp knife']}),

  chickenRecipe({id:'chicken-primavera-fettuccine',title:'Chicken primavera fettuccine',description:'Seared chicken breasts with fettuccine, zucchini, peppers, spinach, and parmesan.',cuisine:'Italian-inspired',prepMinutes:18,cookMinutes:24,difficulty:'Easy',estimatedCost:'10.30',caloriesPerServing:720,proteinGramsPerServing:55,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('fettuccine','Fettuccine','6','oz'),ing('zucchini','Zucchini','1','count'),ing('bell-pepper','Bell pepper','1','count'),ing('spinach','Baby spinach','3','oz'),ing('parmesan','Parmesan','0.5','cup'),ing('olive-oil','Extra virgin olive oil','1.5','tbsp')],steps:['Bring a pot of water to a boil. Cut zucchini into 1/4-inch half-moons and pepper into 1/4-inch strips; pound chicken to an even 3/4 inch.','Cook fettuccine to the shortest package time. Reserve 3/4 cup pasta water, drain, and do not rinse.','Heat 1 tablespoon olive oil over medium-high. Sear chicken 5 to 6 minutes, flip, lower to medium, and cook 5 to 7 minutes until opaque white in the thickest center; rest 5 minutes.','Add remaining oil, zucchini, and pepper to the skillet over medium-high. Cook 5 minutes, add spinach for 1 minute, then lower the heat and toss in pasta, parmesan, and 1/4 cup pasta water.','Add more pasta water a spoonful at a time until glossy. Slice each rested breast and place one complete breast on each vegetable-pasta serving.'],tags:['vegetables','pasta','colorful'],equipment:['Medium pot','Large skillet','Tongs']}),

  chickenRecipe({id:'slap-ya-mama-chicken-green-beans',title:'Slap Ya Mama chicken with green beans',description:'Bold pan-seared chicken breasts with tomato rice and blistered green beans.',cuisine:'Cajun-inspired',prepMinutes:10,cookMinutes:26,difficulty:'Easy',estimatedCost:'8.40',caloriesPerServing:620,proteinGramsPerServing:51,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('green-beans','Green beans','8','oz'),ing('red-tomato-sauce','Red tomato sauce','0.5','cup'),ing('slap-ya-mama','Slap Ya Mama seasoning','1','tsp'),ing('chicken-bouillon','Chicken bouillon','0.5','tsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Rinse rice and put it in the rice cooker with tomato sauce, bouillon, and enough water to total 1 1/4 cups liquid. Stir once and start the white-rice cycle.','Trim green bean stem ends. Pound chicken to 3/4 inch and season lightly with Slap Ya Mama, remembering the blend contains salt.','Heat canola oil over medium-high. Cook chicken 5 to 6 minutes untouched, flip, lower to medium, and cook 5 to 7 minutes until the thickest center is opaque white; rest 5 minutes.','Add green beans and 2 tablespoons water to the skillet. Cover over medium heat for 3 minutes, uncover, raise to medium-high, and cook 3 minutes until blistered and tender.','Fluff tomato rice. Put one whole breast on each plate with half the rice and beans, spooning resting juices over the chicken.'],tags:['cajun','rice','green-beans'],equipment:['Rice cooker','Large skillet','Tongs']}),

  chickenRecipe({id:'lemon-broth-chicken',title:'Lemon broth chicken with parmesan rice',description:'A bright chicken-breast pan sauce with lemon, broth, spinach, and parmesan rice.',cuisine:'Mediterranean-inspired',prepMinutes:12,cookMinutes:24,difficulty:'Easy',estimatedCost:'8.70',caloriesPerServing:610,proteinGramsPerServing:53,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('lemon','Lemon','1','count'),ing('chicken-broth','Chicken broth','0.75','cup'),ing('spinach','Baby spinach','4','oz'),ing('parmesan','Parmesan','0.5','cup'),ing('olive-oil','Extra virgin olive oil','1','tbsp')],steps:['Start rinsed rice in the rice cooker with 1 1/4 cups water. Zest the yellow surface of the lemon without scraping the bitter white layer, then cut and juice it.','Pound chicken to 3/4 inch and season with salt and pepper. Heat olive oil over medium-high and sear chicken 5 to 6 minutes without moving.','Flip, lower to medium, and cook another 5 to 7 minutes. Check the thickest center for opaque white meat, then rest chicken on a clean plate for 5 minutes.','Add broth, lemon zest, and 1 tablespoon lemon juice to the skillet over medium. Scrape the pan and simmer 3 minutes, then add spinach and stir 1 to 2 minutes until wilted.','Fold parmesan into rice. Serve one breast per plate with rice and spinach, spooning the lemon pan sauce over the chicken; add more lemon only after tasting.'],tags:['lemon','pan-sauce','rice'],equipment:['Rice cooker','Large skillet','Citrus zester']}),

  chickenRecipe({id:'teriyaki-pineapple-chicken',title:'Teriyaki pineapple chicken bowls',description:'Chicken breast chunks, pineapple, peppers, and broccoli in teriyaki sauce over rice.',cuisine:'Japanese-inspired',prepMinutes:15,cookMinutes:20,difficulty:'Easy',estimatedCost:'9.70',caloriesPerServing:680,proteinGramsPerServing:51,cleanup:2,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('pineapple','Pineapple chunks','1','cup'),ing('bell-pepper','Bell pepper','1','count'),ing('broccoli','Broccoli','6','oz'),ing('teriyaki-sauce','Teriyaki sauce','0.5','cup'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Start rinsed rice in the rice cooker with 1 1/4 cups water. Drain pineapple well, cut pepper into 1/2-inch squares, and cut broccoli into small florets.','Cut each breast into 1-inch cubes. Heat canola oil in a wide skillet over medium-high, spread chicken in one layer, and sear 3 minutes without moving.','Turn chicken pieces and cook 3 to 4 minutes more. Cut the largest cube; when its center is opaque white, transfer all chicken to a clean bowl.','Add pepper and broccoli with 2 tablespoons water, cover for 2 minutes, then uncover and stir-fry 3 minutes. Add pineapple and cook 2 minutes until its edges begin to brown.','Return chicken and pour in teriyaki sauce. Bubble for 1 to 2 minutes, then divide over rice so each bowl gets the pieces from one breast.'],tags:['sweet-savory','rice-bowl','teriyaki'],equipment:['Rice cooker','Wide skillet','Cutting board']}),

  chickenRecipe({id:'smoky-chicken-sweet-potato',title:'Smoky chicken and sweet potato plates',description:'Air-fried paprika chicken breasts, sweet-potato cubes, and broccoli with yum yum sauce.',cuisine:'American',prepMinutes:15,cookMinutes:25,difficulty:'Easy',estimatedCost:'9.10',caloriesPerServing:600,proteinGramsPerServing:50,cleanup:1,leftoverQuality:4,ingredients:[ing('chicken','Chicken breast','2','count'),ing('sweet-potato','Sweet potato','1','lb'),ing('broccoli','Broccoli','8','oz'),ing('smoked-paprika','Smoked paprika','1.5','tsp'),ing('garlic-salt','Garlic salt','0.75','tsp'),ing('yum-yum-sauce','Yum yum sauce','2','tbsp'),ing('canola-oil','Canola oil','1.5','tbsp')],steps:['Preheat the air fryer to 390°F. Peel sweet potato and cut it into even 1/2-inch cubes; toss with 1 tablespoon oil, half the paprika, and half the garlic salt.','Air-fry sweet potato 10 minutes, shaking after 5 minutes. Cut broccoli into small florets while it cooks.','Pound chicken to 3/4 inch, rub with remaining oil, paprika, and garlic salt, then add it beside the sweet potato in one layer. Air-fry 6 minutes.','Flip chicken and add broccoli. Cook 5 to 7 minutes more, then cut into the thickest breast to check for opaque white meat; rest chicken 5 minutes while vegetables cook 2 minutes longer if needed.','Serve one breast per plate with half the sweet potato and broccoli. Spoon 1 tablespoon yum yum sauce over each chicken breast.'],tags:['air-fryer','smoky','vegetables'],equipment:['Air fryer','Mixing bowl','Tongs']}),

  chickenRecipe({id:'garlic-breadcrumb-chicken-zucchini',title:'Garlic breadcrumb chicken with zucchini',description:'Crisp air-fryer chicken breasts with tomato zucchini and parmesan linguine.',cuisine:'Italian-inspired',prepMinutes:20,cookMinutes:22,difficulty:'Medium',estimatedCost:'10.10',caloriesPerServing:750,proteinGramsPerServing:59,cleanup:3,leftoverQuality:3,ingredients:[ing('chicken','Chicken breast','2','count'),ing('breadcrumbs','Garlic & herb Progresso bread crumbs','0.75','cup'),ing('eggs','Egg','1','count'),ing('zucchini','Zucchini','1','count'),ing('red-tomato-sauce','Red tomato sauce','1','cup'),ing('linguine','Linguine','6','oz'),ing('olive-oil','Extra virgin olive oil','1','tbsp')],steps:['Preheat the air fryer to 390°F. Pound each chicken breast to an even 1/2 to 3/4 inch; beat the egg in one shallow bowl and put breadcrumbs in another.','Dip chicken in egg, let excess drip off, then press firmly into breadcrumbs. Brush or spray with half the olive oil and air-fry in one layer for 6 minutes.','Flip and air-fry 5 to 7 minutes more. Cut into the thickest piece to confirm opaque white meat, then rest on a clean plate.','Meanwhile, boil linguine according to the package. Slice zucchini into 1/4-inch half-moons and cook in remaining oil over medium-high for 5 minutes; add tomato sauce and simmer 3 minutes.','Drain linguine and toss with tomato zucchini. Serve one whole crisp breast with each pasta portion, keeping sauce mostly beneath the chicken so the coating stays crunchy.'],tags:['air-fryer','crispy','pasta'],equipment:['Air fryer','Medium pot','Two shallow bowls','Skillet']}),

  chickenRecipe({id:'cajun-chicken-corn-rice',title:'Cajun chicken corn rice skillet',description:'One-pan chicken breast, corn, peppers, and tomato-seasoned Minute Rice.',cuisine:'Cajun-inspired',prepMinutes:12,cookMinutes:22,difficulty:'Easy',estimatedCost:'8.10',caloriesPerServing:640,proteinGramsPerServing:52,cleanup:1,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('minute-rice','Minute Rice','1','cup'),ing('corn','Frozen corn','1','cup'),ing('bell-pepper','Bell pepper','1','count'),ing('red-tomato-sauce','Red tomato sauce','0.75','cup'),ing('slap-ya-mama','Slap Ya Mama seasoning','1','tsp'),ing('canola-oil','Canola oil','1','tbsp')],steps:['Cut pepper into 1/2-inch squares. Pound chicken breasts to an even 3/4 inch and season lightly with Slap Ya Mama.','Heat canola oil in a deep skillet over medium-high. Cook chicken 5 to 6 minutes on the first side, flip, lower to medium, and cook 5 to 7 minutes until opaque white in the thickest center; rest 5 minutes.','Add pepper and corn to the skillet over medium-high and cook 4 minutes. Stir in tomato sauce and the package amount of water needed for 1 cup Minute Rice, then bring to a boil.','Stir in rice, cover, remove from heat, and let stand for the package time, usually 5 minutes. Fluff with a fork and taste before adding salt.','Put one whole chicken breast on each plate and divide the tomato-corn rice beside it. Spoon any resting juices over the chicken.'],tags:['one-pan','cajun','rice'],equipment:['Deep skillet with lid','Tongs','Cutting board']}),

  chickenRecipe({id:'parmesan-spinach-chicken-rice',title:'Parmesan spinach chicken rice bowls',description:'Seared chicken breasts with creamy-tasting parmesan spinach rice made without heavy cream.',cuisine:'Italian-inspired',prepMinutes:10,cookMinutes:25,difficulty:'Easy',estimatedCost:'8.90',caloriesPerServing:650,proteinGramsPerServing:56,cleanup:2,leftoverQuality:5,ingredients:[ing('chicken','Chicken breast','2','count'),ing('basmati-rice','Basmati rice','0.75','cup'),ing('spinach','Baby spinach','5','oz'),ing('parmesan','Parmesan','0.75','cup'),ing('chicken-broth','Chicken broth','0.5','cup'),ing('garlic-salt','Garlic salt','0.5','tsp'),ing('olive-oil','Extra virgin olive oil','1','tbsp')],steps:['Rinse and start rice in the rice cooker with 1 cup water and 1/2 cup chicken broth. Pound chicken to 3/4 inch and season lightly with garlic salt.','Heat olive oil over medium-high. Cook chicken 5 to 6 minutes without moving, flip, lower to medium, and cook another 5 to 7 minutes.','Cut into the thickest center to confirm opaque white meat with no pink, then rest chicken on a clean plate for 5 minutes.','Stir spinach into the hot cooked rice a handful at a time, closing the cooker lid for 1 minute between additions until wilted. Fold in parmesan and 2 tablespoons hot water if the rice seems dry.','Divide parmesan spinach rice between bowls. Leave the chicken whole or slice after resting, placing one complete breast over each bowl.'],tags:['rice-bowl','spinach','parmesan'],equipment:['Rice cooker','Large skillet','Tongs']})
);

